#!/usr/bin/env python3
"""Offline BGP relationship inference and route leak scoring service.

Reads one JSON request from stdin, normalizes AS paths (IXP removal,
prepending collapse), peels peripheral links simultaneously, performs exact
joint inference over the core link relationship variables, scores queries
against declared relationships and writes one JSON response to stdout.
"""

import json
import re
import sys
from fractions import Fraction
from itertools import product as _product

# Relationship types: 0 = c2p, 1 = p2p, 2 = p2c.
# g(L, R) table, rows L, columns R.
G_TABLE = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
INV = (2, 1, 0)                      # inverse type: c2p <-> p2c, p2p fixed
ASN_MAX = 4294967295
MAX_BYTES = 4194304
MAX_RIB_LINKS = 4096
MAX_CORE_LINKS = 64
ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,64}\Z')
REL_CODES = {'c2p': 0, 'p2p': 1, 'p2c': 2}
ONE_HOT = ((1, 0, 0), (0, 1, 0), (0, 0, 1))
UNIFORM = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))


class Invalid(Exception):
    """Schema, bounds, order or width violation."""


class Internal(Exception):
    """Should be unreachable; used as a development guard."""


# ------------------------------------------------------------------ output

def emit(obj):
    sys.stdout.write(json.dumps(obj, allow_nan=False))
    sys.stdout.write('\n')


# ------------------------------------------------------------------ input

def read_document():
    try:
        raw = sys.stdin.buffer.read(MAX_BYTES + 1)
    except Exception:
        return None
    if len(raw) > MAX_BYTES:
        return None
    try:
        text = raw.decode('utf-8')
    except Exception:
        return None

    def pairs_hook(pairs):
        obj = {}
        for key, value in pairs:
            if key in obj:
                raise ValueError('duplicate object key')
            obj[key] = value
        return obj

    def reject_constant(name):
        raise ValueError('nonfinite literal ' + name)

    try:
        return json.loads(text, object_pairs_hook=pairs_hook,
                          parse_constant=reject_constant)
    except Exception:
        return None


def _valid_asn(x):
    return type(x) is int and 1 <= x <= ASN_MAX


def _valid_link(lnk):
    if type(lnk) is not list or len(lnk) != 2:
        raise Invalid()
    u, v = lnk[0], lnk[1]
    if not _valid_asn(u) or not _valid_asn(v) or u == v:
        raise Invalid()
    return u, v


def _valid_path(path):
    if type(path) is not list or len(path) > 64:
        raise Invalid()
    for asn in path:
        if not _valid_asn(asn):
            raise Invalid()


def validate(doc):
    if type(doc) is not dict:
        raise Invalid()
    if set(doc.keys()) != {'version', 'ixps', 'rib', 'priors', 'declared',
                           'order', 'queries'}:
        raise Invalid()
    if type(doc['version']) is not int or doc['version'] != 1:
        raise Invalid()

    ixps = doc['ixps']
    if type(ixps) is not list or len(ixps) > 1024:
        raise Invalid()
    for x in ixps:
        if not _valid_asn(x):
            raise Invalid()
    if len(set(ixps)) != len(ixps):
        raise Invalid()

    rib = doc['rib']
    if type(rib) is not list or len(rib) > 2000:
        raise Invalid()
    rib_records = []
    total_len = 0
    for rec in rib:
        if type(rec) is not dict or set(rec.keys()) != {'path', 'count'}:
            raise Invalid()
        path = rec['path']
        _valid_path(path)
        count = rec['count']
        if type(count) is not int or count < 1 or count > 1000000:
            raise Invalid()
        total_len += len(path)
        rib_records.append((list(path), count))
    if total_len > 40000:
        raise Invalid()

    priors = {}
    raw = doc['priors']
    if type(raw) is not list or len(raw) > 2000:
        raise Invalid()
    for rec in raw:
        if type(rec) is not dict or set(rec.keys()) != {'link', 'weights'}:
            raise Invalid()
        u, v = _valid_link(rec['link'])
        w = rec['weights']
        if type(w) is not list or len(w) != 3:
            raise Invalid()
        for x in w:
            if type(x) is not int or x < 0 or x > 1000000:
                raise Invalid()
        if w[0] + w[1] + w[2] <= 0:
            raise Invalid()
        key = (u, v) if u < v else (v, u)
        if key in priors:
            raise Invalid()
        priors[key] = (w[0], w[1], w[2]) if u < v else (w[2], w[1], w[0])

    declared = {}
    raw = doc['declared']
    if type(raw) is not list or len(raw) > 2000:
        raise Invalid()
    for rec in raw:
        if type(rec) is not dict or set(rec.keys()) != {'link', 'rel'}:
            raise Invalid()
        u, v = _valid_link(rec['link'])
        rel = rec['rel']
        if type(rel) is not str or rel not in REL_CODES:
            raise Invalid()
        code = REL_CODES[rel]
        key = (u, v) if u < v else (v, u)
        if key in declared:
            raise Invalid()
        hot = ONE_HOT[code] if u < v else ONE_HOT[INV[code]]
        declared[key] = tuple(Fraction(x) for x in hot)

    order = []
    raw = doc['order']
    if type(raw) is not list:
        raise Invalid()
    for pair in raw:
        u, v = _valid_link(pair)
        if u >= v:
            raise Invalid()
        order.append((u, v))

    queries = []
    raw = doc['queries']
    if type(raw) is not list or len(raw) > 512:
        raise Invalid()
    seen_ids = set()
    for rec in raw:
        if type(rec) is not dict or set(rec.keys()) != {'id', 'path',
                                                        'threshold'}:
            raise Invalid()
        qid = rec['id']
        if type(qid) is not str or not ID_RE.match(qid):
            raise Invalid()
        if qid in seen_ids:
            raise Invalid()
        seen_ids.add(qid)
        path = rec['path']
        _valid_path(path)
        th = rec['threshold']
        if type(th) is not list or len(th) != 2:
            raise Invalid()
        a, b = th[0], th[1]
        if type(a) is not int or type(b) is not int:
            raise Invalid()
        if a < 0 or a > b or b > 1000000 or b < 1:
            raise Invalid()
        queries.append((qid, list(path), Fraction(a, b)))

    return {'ixps': ixps, 'rib': rib_records, 'priors': priors,
            'declared': declared, 'order': order, 'queries': queries}


# ------------------------------------------------------------- normalizing

def normalize_path(path, ixpset):
    out = []
    for asn in path:
        if asn in ixpset:
            continue
        if out and out[-1] == asn:
            continue
        out.append(asn)
    return out


def _canon(a, b):
    return (a, b) if a < b else (b, a)


# ----------------------------------------------------------------- peeling

def peel(entries):
    """Simultaneous peripheral peeling.

    entries: list of (path_tuple, count).  Returns (final_paths, rounds)
    where final_paths maps surviving directed path tuples to summed counts
    and rounds maps every removed canonical link to its peeling round.
    """
    paths = []
    counts = []
    alive = []
    link_cnt = {}
    block = {}
    containing = {}
    pending = set()

    def apply_path(p, pid, add):
        first = p[0]
        last = p[-1]
        for i in range(len(p) - 1):
            a = p[i]
            b = p[i + 1]
            if a < b:
                key = (a, b)
            else:
                key = (b, a)
            pending.add(key)
            if add:
                ent = block.get(key)
                if ent is None:
                    ent = [0, 0]
                    block[key] = ent
                    link_cnt[key] = 0
                    containing[key] = set()
                link_cnt[key] += 1
                containing[key].add(pid)
                if a != first and a != last:
                    ent[0 if a < b else 1] += 1
                if b != first and b != last:
                    ent[1 if a < b else 0] += 1
            else:
                ent = block[key]
                link_cnt[key] -= 1
                containing[key].discard(pid)
                if a != first and a != last:
                    ent[0 if a < b else 0] -= 1
                if b != first and b != last:
                    ent[1 if a < b else 0] -= 1

    for path, count in entries:
        pid = len(paths)
        paths.append(path)
        counts.append(count)
        alive.append(True)
        apply_path(path, pid, True)

    rounds = {}
    rnd = 0
    while True:
        rnd += 1
        marked = set()
        for key in pending:
            if link_cnt.get(key, 0) > 0:
                ent = block[key]
                if ent[0] == 0 or ent[1] == 0:
                    marked.add(key)
        pending = set()
        if not marked:
            break
        for key in marked:
            rounds[key] = rnd
        affected = set()
        for key in marked:
            affected.update(containing[key])
        for pid in affected:
            p = paths[pid]
            apply_path(p, pid, False)
            fl = _canon(p[0], p[1])
            ll = _canon(p[-2], p[-1])
            start = 1 if fl in marked else 0
            stop = len(p) - 1 if ll in marked else len(p)
            q = p[start:stop]
            if len(q) >= 2:
                paths[pid] = q
                apply_path(q, pid, True)
            else:
                alive[pid] = False

    final = {}
    for pid in range(len(paths)):
        if alive[pid]:
            key = paths[pid]
            final[key] = final.get(key, 0) + counts[pid]
    return final, rounds


# ------------------------------------------------------- factors / inference

def _convert_spec(spec, var_index):
    """spec is (None, const_type) or a directed link (from, to)."""
    if spec[0] is None:
        return (None, spec[1])
    x, y = spec
    if x < y:
        return (var_index[(x, y)], False)
    return (var_index[(y, x)], True)


def collect_occurrences(final_paths):
    """Map canonical core link -> list of (count, lspec, rspec)."""
    occs = {}
    for p, cnt in final_paths.items():
        n = len(p)
        for i in range(n - 1):
            a = p[i]
            b = p[i + 1]
            if a < b:
                oriented = p
                oi = i
            else:
                oriented = p[::-1]
                oi = n - 2 - i
            u, v = oriented[oi], oriented[oi + 1]
            if oi == 0:
                lspec = (None, 0)                 # missing predecessor: c2p
            else:
                lspec = (oriented[oi - 1], u)     # directed x -> u
            if oi + 2 == n:
                rspec = (None, 2)                 # missing successor: p2c
            else:
                rspec = (v, oriented[oi + 2])     # directed v -> y
            occs.setdefault((u, v), []).append((cnt, lspec, rspec))
    return occs


def build_factor(link, occ_list, var_index):
    cvar = var_index[link]
    occ = []
    ctx = set()
    for (cnt, L, R) in occ_list:
        ls = _convert_spec(L, var_index)
        rs = _convert_spec(R, var_index)
        occ.append((cnt, ls, rs))
        for s in (ls, rs):
            if s[0] is not None:
                ctx.add(s[0])
    ctx.discard(cvar)
    scope = (cvar,) + tuple(sorted(ctx))
    pos = {v: i for i, v in enumerate(scope)}
    table = {}
    for (cnt, ls, rs) in occ:
        lvar, lflag = ls
        rvar, rflag = rs
        if lvar is None:
            lopts = ((None, lflag),)
        else:
            lopts = tuple((val, val if not lflag else INV[val])
                          for val in (0, 1, 2))
        if rvar is None:
            ropts = ((None, rflag),)
        else:
            ropts = tuple((val, val if not rflag else INV[val])
                          for val in (0, 1, 2))
        for (lval, ltype) in lopts:
            for (rval, rtype) in ropts:
                if (lvar is not None and rvar is not None
                        and lvar == rvar and lval != rval):
                    continue
                center = G_TABLE[ltype][rtype]
                if lvar == cvar and lval != center:
                    continue
                if rvar == cvar and rval != center:
                    continue
                key = [0] * len(scope)
                key[pos[cvar]] = center
                if lvar is not None:
                    key[pos[lvar]] = lval
                if rvar is not None and rvar != lvar:
                    key[pos[rvar]] = rval
                kt = tuple(key)
                table[kt] = table.get(kt, 0) + cnt
    return (scope, table)


def factor_product(pots):
    """Multiply factors given as (scope tuple, table dict) pairs."""
    if not pots:
        return (), {(): 1}
    if len(pots) == 1:
        return pots[0]
    allvars = set()
    for scope, _ in pots:
        allvars.update(scope)
    scope = tuple(sorted(allvars))
    pos = {v: i for i, v in enumerate(scope)}
    prepared = []
    for s, t in pots:
        idx = tuple(pos[v] for v in s)
        prepared.append((idx, t))
    table = {}
    for assign in _product((0, 1, 2), repeat=len(scope)):
        val = 1
        for idx, t in prepared:
            sub = t.get(tuple(map(assign.__getitem__, idx)))
            if sub is None:
                val = 0
                break
            val *= sub
        if val:
            table[assign] = val
    return scope, table


def factor_marginalize(scope, table, keepset):
    """Sum out every factor variable not in keepset."""
    keep_idx = [i for i, v in enumerate(scope) if v in keepset]
    if not keep_idx:
        return (), {(): sum(table.values())}
    newscope = tuple(scope[i] for i in keep_idx)
    newtable = {}
    for key, val in table.items():
        nk = tuple(map(key.__getitem__, keep_idx))
        newtable[nk] = newtable.get(nk, 0) + val
    return newscope, newtable


def sum_out_var(scope, table, var):
    if var not in scope:
        # Summing over a variable absent from the scope multiplies by 3.
        if not table:
            return scope, {}
        return scope, {k: 3 * v for k, v in table.items()}
    keep = set(scope)
    keep.discard(var)
    return factor_marginalize(scope, table, keep)


def check_elimination_width(factors, n):
    adj = {i: set() for i in range(n)}
    for scope, _ in factors:
        for a in scope:
            for b in scope:
                if a != b:
                    adj[a].add(b)
    cur = {i: set(adj[i]) for i in range(n)}
    for i in range(n):
        nbrs = cur.pop(i)
        if len(nbrs) > 4:
            raise Invalid()
        for a in nbrs:
            cur[a].discard(i)
        for a in nbrs:
            for b in nbrs:
                if a != b:
                    cur[a].add(b)


def infer(factors, n):
    """Exact inference. Returns (Z, {var index: [num_t0, num_t1, num_t2]})."""
    if n == 0:
        return 1, {}
    bucket = [[] for _ in range(n)]
    for f in factors:
        bucket[min(f[0])].append(f)
    children = [[] for _ in range(n)]
    H = [None] * n
    Mmsg = [None] * n
    roots = []
    for i in range(n):
        pots = list(bucket[i])
        for c in children[i]:
            pots.append(Mmsg[c])
        scope, table = factor_product(pots)
        if i not in scope:
            raise Internal('bucket variable missing from scope')
        H[i] = (scope, table)
        mscope, mtable = sum_out_var(scope, table, i)
        Mmsg[i] = (mscope, mtable)
        if mscope:
            children[mscope[0]].append(i)
        else:
            roots.append(i)

    Z = 1
    rootval = {}
    for i in roots:
        val = Mmsg[i][1].get((), 0)
        rootval[i] = val
        Z *= val
        if Z == 0:
            break
    if Z == 0:
        return 0, None

    down = [None] * n
    for i in roots:
        down[i] = ((), {(): Z // rootval[i]})

    marg = {}
    for i in range(n - 1, -1, -1):
        bscope, btable = factor_product([H[i], down[i]])
        k = bscope.index(i)
        nums = [0, 0, 0]
        for key, val in btable.items():
            nums[key[k]] += val
        marg[i] = nums
        base = list(bucket[i])
        base.append(down[i])
        for c in children[i]:
            pots = list(base)
            for k2 in children[i]:
                if k2 != c:
                    pots.append(Mmsg[k2])
            pscope, ptable = factor_product(pots)
            sep = set(Mmsg[c][0])
            dscope, dtable = factor_marginalize(pscope, ptable, sep)
            down[c] = (dscope, dtable)
    return Z, marg


# ------------------------------------------------------------------ scoring

def compute_full(vecs):
    """Sum of probabilities of c2p* p2p p2c* and c2p* p2c* sequences."""
    bits = 0
    for vec in vecs:
        m = 0
        for x in vec:
            m = max(m, x.numerator.bit_length() + x.denominator.bit_length())
        bits += m
    if bits <= 6000:
        up = Fraction(1)
        peer = Fraction(0)
        down = Fraction(0)
        for (u, h, d) in vecs:
            up, peer, down = up * u, up * h, (up + peer + down) * d
        return float(up + peer + down)
    fvecs = [(float(u), float(h), float(d)) for (u, h, d) in vecs]
    up = 1.0
    peer = 0.0
    down = 0.0
    for (u, h, d) in fvecs:
        up, peer, down = up * u, up * h, (up + peer + down) * d
    return up + peer + down


# -------------------------------------------------------------------- solve

def solve(spec):
    ixpset = frozenset(spec['ixps'])
    priors = spec['priors']
    declared = spec['declared']
    order_links = spec['order']

    agg = {}
    for path, count in spec['rib']:
        p = normalize_path(path, ixpset)
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        key = tuple(p)
        agg[key] = agg.get(key, 0) + count

    orig_links = set()
    for p in agg:
        for i in range(len(p) - 1):
            orig_links.add(_canon(p[i], p[i + 1]))
    if len(orig_links) > MAX_RIB_LINKS:
        raise Invalid()

    final_paths, rounds = peel(list(agg.items()))

    core_links = set()
    for p in final_paths:
        for i in range(len(p) - 1):
            core_links.add(_canon(p[i], p[i + 1]))
    if len(core_links) > MAX_CORE_LINKS:
        raise Invalid()

    if len(order_links) != len(core_links):
        raise Invalid()
    seen = set()
    for link in order_links:
        if link not in core_links or link in seen:
            raise Invalid()
        seen.add(link)
    var_index = {link: i for i, link in enumerate(order_links)}

    occs = collect_occurrences(final_paths)
    factors = []
    for link in order_links:
        occ_list = occs.get(link)
        if occ_list is None:
            factors.append(((var_index[link],), {}))
        else:
            factors.append(build_factor(link, occ_list, var_index))

    check_elimination_width(factors, len(order_links))

    Z, marg = infer(factors, len(order_links))
    if Z == 0:
        return {'error': 'zero-partition'}

    priorfrac = {}
    for key, w in priors.items():
        s = w[0] + w[1] + w[2]
        priorfrac[key] = (Fraction(w[0], s), Fraction(w[1], s),
                          Fraction(w[2], s))

    margfrac = {}
    for link, idx in var_index.items():
        nums = marg[idx]
        margfrac[link] = (Fraction(nums[0], Z), Fraction(nums[1], Z),
                          Fraction(nums[2], Z))

    links_out = []
    for link in sorted(orig_links):
        if link in var_index:
            rnd = 0
            prob = margfrac[link]
        else:
            rnd = rounds[link]
            prob = priorfrac.get(link, UNIFORM)
        links_out.append({'link': [link[0], link[1]], 'round': rnd,
                          'prob': [float(x) for x in prob]})

    def scoring_vector(a, b):
        if a < b:
            key = (a, b)
            rev = False
        else:
            key = (b, a)
            rev = True
        if key in declared:
            vec = declared[key]
        elif key in margfrac:
            vec = margfrac[key]
        elif key in priorfrac:
            vec = priorfrac[key]
        else:
            vec = UNIFORM
        if rev:
            return (vec[2], vec[1], vec[0])
        return vec

    queries_out = []
    for (qid, raw_path, thr) in spec['queries']:
        p = normalize_path(raw_path, ixpset)
        rec = {'id': qid, 'path': p, 'status': 'ok', 'score': None,
               'full': None, 'witness': None, 'leaked': None}
        if len(set(p)) != len(p):
            rec['status'] = 'loop'
            queries_out.append(rec)
            continue
        if len(p) <= 2:
            rec['score'] = 1.0
            rec['full'] = 1.0
            rec['leaked'] = False
            queries_out.append(rec)
            continue
        vecs = [scoring_vector(p[i], p[i + 1]) for i in range(len(p) - 1)]
        triples = [vecs[i][0] + vecs[i + 1][2]
                   - vecs[i][0] * vecs[i + 1][2]
                   for i in range(len(vecs) - 1)]
        score = min(triples)
        witness = triples.index(score)
        rec['score'] = float(score)
        rec['full'] = compute_full(vecs)
        rec['witness'] = witness
        rec['leaked'] = bool(score < thr)
        queries_out.append(rec)

    return {'version': 1, 'links': links_out, 'queries': queries_out}


# -------------------------------------------------------------------- main

def main():
    doc = read_document()
    if doc is None:
        emit({'error': 'invalid'})
        return
    try:
        spec = validate(doc)
    except Invalid:
        emit({'error': 'invalid'})
        return
    try:
        result = solve(spec)
    except Invalid:
        emit({'error': 'invalid'})
        return
    except Exception:
        emit({'error': 'invalid'})
        return
    emit(result)


if __name__ == '__main__':
    main()
