import ref, main as M


def forward_Z(factors, n):
    """Plain forward bucket elimination partition function."""
    if n == 0:
        return 1
    bucket = [[] for _ in range(n)]
    for f in factors:
        bucket[min(f[0])].append(f)
    children = [[] for _ in range(n)]
    msg = [None] * n
    Z = 1
    for i in range(n):
        pots = list(bucket[i])
        for c in children[i]:
            pots.append(msg[c])
        scope, table = M.factor_product(pots)
        mscope, mtable = M.sum_out_var(scope, table, i)
        msg[i] = (mscope, mtable)
        if mscope:
            children[mscope[0]].append(i)
        else:
            Z *= mtable.get((), 0)
            if Z == 0:
                return 0
    return Z


